<section class="components-page form-elements-page">
  <div class="card app-card component-section"><div class="card-header"><h5 class="card-title mb-0">Basic Sliders</h5></div><div class="card-body form-stack"><div class="slider-field"><label class="form-label" for="sliderBasic">Basic</label><input type="range" class="form-range" id="sliderBasic" min="0" max="100" value="50" data-range-value><span class="range-value">50</span></div><div class="slider-field"><label class="form-label" for="sliderMinMax">Min-Max</label><input type="range" class="form-range" id="sliderMinMax" min="20" max="80" value="35" data-range-value><span class="range-value">35</span></div><div class="slider-field"><label class="form-label" for="sliderStep">Step</label><input type="range" class="form-range" id="sliderStep" min="0" max="100" step="10" value="40" data-range-value><span class="range-value">40</span></div></div></div>
  <div class="row g-4"><div class="col-xl-6"><div class="card app-card component-section"><div class="card-header"><h5 class="card-title mb-0">Colors</h5></div><div class="card-body form-stack"><input type="range" class="form-range range-primary" min="0" max="100" value="20"><input type="range" class="form-range range-success" min="0" max="100" value="45"><input type="range" class="form-range range-warning" min="0" max="100" value="70"><input type="range" class="form-range range-danger" min="0" max="100" value="85"></div></div></div><div class="col-xl-6"><div class="card app-card component-section"><div class="card-header"><h5 class="card-title mb-0">Vertical</h5></div><div class="card-body"><div class="vertical-slider-group"><input type="range" class="form-range vertical-range" min="0" max="100" value="25" aria-label="Vertical slider 25"><input type="range" class="form-range vertical-range range-success" min="0" max="100" value="50" aria-label="Vertical slider 50"><input type="range" class="form-range vertical-range range-warning" min="0" max="100" value="75" aria-label="Vertical slider 75"></div></div></div></div></div>
</section>